use hash_ring::HashRing;
use std::collections::HashMap;

#[test]
fn every_key_maps_to_a_current_node() {
    let ring = HashRing::new(vec!["a".into(), "b".into(), "c".into()], 50);
    for i in 0..200 {
        let node = ring.get_node(&format!("key-{}", i));
        assert!(node == "a" || node == "b" || node == "c");
    }
}

#[test]
fn deterministic() {
    let ring = HashRing::new(vec!["a".into(), "b".into(), "c".into()], 50);
    assert_eq!(ring.get_node("stable-key"), ring.get_node("stable-key"));
}

#[test]
fn removing_a_node_only_moves_that_nodes_own_keys() {
    let nodes: Vec<String> = vec!["n0", "n1", "n2", "n3", "n4"].into_iter().map(String::from).collect();
    let mut ring = HashRing::new(nodes, 100);
    let keys: Vec<String> = (0..1000).map(|i| format!("key-{}", i)).collect();
    let before: HashMap<String, String> = keys.iter().map(|k| (k.clone(), ring.get_node(k))).collect();

    ring.remove_node("n2");

    let mut moved = 0;
    for k in &keys {
        let after = ring.get_node(k);
        if &after != before.get(k).unwrap() {
            moved += 1;
            assert_eq!(before.get(k).unwrap(), "n2", "key {} moved but was not on removed node n2", k);
        }
        assert_ne!(after, "n2");
    }
    assert!(moved > 0, "expected removing a node to move at least some keys");
}

