use std::collections::hash_map::DefaultHasher;
use std::collections::BTreeMap;
use std::hash::{Hash, Hasher};

fn hash_of(s: &str) -> u64 {
    let mut h = DefaultHasher::new();
    s.hash(&mut h);
    h.finish()
}

pub struct HashRing {
    replicas: usize,
    ring: BTreeMap<u64, String>,
}

impl HashRing {
    pub fn new(nodes: Vec<String>, replicas: usize) -> Self {
        let mut r = HashRing { replicas, ring: BTreeMap::new() };
        for node in nodes {
            r.add_node(&node);
        }
        r
    }

    pub fn add_node(&mut self, node: &str) {
        for i in 0..self.replicas {
            let point = hash_of(&format!("{}:{}", node, i));
            self.ring.insert(point, node.to_string());
        }
    }

    pub fn remove_node(&mut self, node: &str) {
        for i in 0..self.replicas {
            let point = hash_of(&format!("{}:{}", node, i));
            self.ring.remove(&point);
        }
    }

    pub fn get_node(&self, key: &str) -> String {
        let point = hash_of(key);
        match self.ring.range(point..).next() {
            Some((_, node)) => node.clone(),
            None => self.ring.values().next().unwrap().clone(),
        }
    }
}

